const queueItem = $('HTTP Request | Claim Next Pending Date').first().json;
const runDate = queueItem.run_date;

function fredVal(nodeName) {
  try {
    const obs = $(nodeName).first().json.observations;
    for (const o of obs) {
      if (o.value && o.value !== '.') return parseFloat(o.value);
    }
    return null;
  } catch(e) { return null; }
}

const us2y    = fredVal('HTTP Request | BT US 2Y - FRED');
const us10y   = fredVal('HTTP Request | BT US 10Y - FRED');
const tips10y = fredVal('HTTP Request | BT TIPS 10Y - FRED');
const de10y   = fredVal('HTTP Request | BT Germany 10Y - FRED');
const vix     = fredVal('HTTP Request | BT VIX - FRED');
const dxy     = fredVal('HTTP Request | BT DXY - FRED');
const wti     = fredVal('HTTP Request | BT WTI - FRED');
const brent   = fredVal('HTTP Request | BT Brent - FRED');
const eurusd  = fredVal('HTTP Request | BT EUR/USD - FRED');
const gbpusd  = fredVal('HTTP Request | BT GBP/USD - FRED');
const usdjpy  = fredVal('HTTP Request | BT USD/JPY - FRED');
const usdcad  = fredVal('HTTP Request | BT USD/CAD - FRED');
const audusd  = fredVal('HTTP Request | BT AUD/USD - FRED');

let gold = null;
try {
  const dayPrices = $('HTTP Request | BT Fetch Day Prices from DB').all().map(i => i.json);
  const goldRow = dayPrices.find(r => r.market === 'XAU/USD');
  gold = goldRow ? parseFloat(goldRow.close_price) : null;
} catch(e) {}

let btc = null;
try {
  btc = parseFloat($('HTTP Request | BT BTC - CoinGecko').first().json.market_data.current_price.usd);
} catch(e) {}

return [{
  json: {
    runDate,
    resolutionDate24h:    queueItem.resolution_date_24h,
    resolutionDate72h:    queueItem.resolution_date_72h,
    resolutionDateWeekly: queueItem.resolution_date_weekly,
    timestamp: `${runDate}T07:00:00.000Z`,
    rates:   { us2y, us10y, tips10y, de10y, vix, dxy, wti, brent },
    prices:  { gold, btc, eurusd, gbpusd, usdjpy, usdcad, audusd },
    spreads: {
      usDeSpread:     (us2y !== null && de10y !== null) ? us2y - de10y : null,
      brentWtiSpread: (brent !== null && wti !== null) ? brent - wti : null
    }
  }
}];

const data = $('Code | BT Fetch Aggregator').first().json;
const ruleset = $('Edit Fields | USD Ruleset').first().json.ruleset;

return [{
  json: {
    model: "claude-sonnet-4-6",
    max_tokens: 16000,
    system: ruleset,
    messages: [{
      role: "user",
      content: `Today's macro data as of ${data.timestamp} (historical date: ${data.runDate}):\n\n${JSON.stringify(data, null, 2)}\n\nPlease provide your full USD directional diagnosis following the output template in Section 14 of your ruleset.`
    }]
  }
}];

const response = $input.first().json;
const upstream = $('Code | BT Fetch Aggregator').first().json;

return [{
  json: {
    diagnosis: response.content[0].text,
    runDate: upstream.runDate,
    resolutionDate24h:    upstream.resolutionDate24h,
    resolutionDate72h:    upstream.resolutionDate72h,
    resolutionDateWeekly: upstream.resolutionDateWeekly
  }
}];

const diagnosis = $input.first().json.diagnosis;

return [{
  json: {
    model: "claude-sonnet-4-6",
    max_tokens: 4000,
    system: `You are a structured data extractor. Given a USD macro diagnosis, extract trading calls in strict JSON format. Output ONLY valid JSON — no other text, no markdown, no preamble.`,
    messages: [{
      role: "user",
      content: `From this diagnosis, extract trading calls for all 9 markets across 3 timeframes (24h, 72h, weekly).

Markets: EUR/USD, USD/JPY, GBP/USD, USD/CAD, AUD/USD, NQ, BTC/USD, XAU/USD, WTI Oil

Return a JSON array of exactly 27 objects, each with:
- market (string)
- timeframe (string: "24h", "72h", or "weekly")
- direction (string: "LONG", "SHORT", or "NO TRADE")
- conviction (number: 1-5)
- rationale (string: one sentence)

DIAGNOSIS:
${diagnosis}`
    }]
  }
}];

const response = $('HTTP Request | BT Extract Calls - Claude API').first().json;
const upstream = $('Code | BT Extract Diagnosis Text').first().json;
const runDate = upstream.runDate;

const rawText = response.content[0].text;
const cleaned = rawText.replace(/```json\n?/g, '').replace(/```/g, '').trim();
const calls = JSON.parse(cleaned);

// Fetch entry prices from market_prices table
const pricesArray = $('HTTP Request | BT Fetch Entry Prices from DB').all().map(i => i.json);

const priceMap = {};
pricesArray.forEach(row => {
  if (!priceMap[row.market]) {
    priceMap[row.market] = parseFloat(row.close_price);
  }
});

const callsWithMeta = calls.map(call => ({
  run_date:        runDate,
  market:          call.market,
  timeframe:       call.timeframe,
  direction:       call.direction,
  conviction:      call.conviction,
  rationale:       call.rationale,
  resolution_date: call.timeframe === '24h'    ? upstream.resolutionDate24h
                 : call.timeframe === '72h'    ? upstream.resolutionDate72h
                 : upstream.resolutionDateWeekly,
  entry_price:     priceMap[call.market] || null,
  status:          'OPEN',
  source:          'donnelly'
}));

return callsWithMeta.map(call => ({ json: call }));

