={{ (() => {
  const d = $('Code | BT Fetch Aggregator').first().json;
  const markets = [
    { price_date: d.runDate, market: 'EUR/USD',  close_price: d.prices.eurusd,  source: 'FRED' },
    { price_date: d.runDate, market: 'GBP/USD',  close_price: d.prices.gbpusd,  source: 'FRED' },
    { price_date: d.runDate, market: 'USD/JPY',  close_price: d.prices.usdjpy,  source: 'FRED' },
    { price_date: d.runDate, market: 'USD/CAD',  close_price: d.prices.usdcad,  source: 'FRED' },
    { price_date: d.runDate, market: 'AUD/USD',  close_price: d.prices.audusd,  source: 'FRED' },
    { price_date: d.runDate, market: 'XAU/USD',  close_price: d.prices.gold,    source: 'AlphaVantage' },
    { price_date: d.runDate, market: 'BTC/USD',  close_price: d.prices.btc,     source: 'CoinGecko' },
    { price_date: d.runDate, market: 'WTI Oil',  close_price: d.rates.wti,      source: 'FRED' }
  ];
  return markets;
})() }}
